children.input:
{
  "project_id": "ccac41ea93214e2d8eed",
  "query": "
select pid, usename, state, wait_event_type, wait_event, query_start, xact_start, now() - xact_start as xact_age, now() - query_start as query_age, left(query, 200) as query
from pg_stat_activity
where state != 'idle'
order by xact_start asc nulls last;
"
}

