children.input:
{
  "project_id": "ccac41ea93214e2d8eed",
  "query": "
select a.pid, a.state, a.query_start, now()-a.xact_start as xact_age, a.wait_event_type, left(a.query,150) as query
from pg_stat_activity a
where a.pid <> pg_backend_pid()
order by a.xact_start asc nulls last;
"
}

